schema:
CREATE TABLE MYNUMBERS (
    NUM INT
);

counterexample:
-- No counterexample exists; the two queries are equivalent. 
-- For example, consider the following INSERTs (try them and observe that both queries yield the same result):

INSERT INTO MYNUMBERS (NUM) VALUES (1);
INSERT INTO MYNUMBERS (NUM) VALUES (1);
INSERT INTO MYNUMBERS (NUM) VALUES (2);
INSERT INTO MYNUMBERS (NUM) VALUES (NULL);

-- Q1 would group as: group for 1 (count=2), group for 2 (count=1), and group for NULL (count=0, since COUNT(NUM) ignores NULL). It would return MAX(2) = 2.
-- Q2 would group as: group for 1 (count=2), group for 2 (count=1), and group for NULL (count=1), but then the CASE returns NULL for the NULL group. The MAX of (2 and NULL) is still 2.
-- Thus, both queries return 2.

