schema:
CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR(255),
    FOLLOWER VARCHAR(255),
    PRIMARY KEY (FOLLOWEE, FOLLOWER),
    CHECK (FOLLOWEE <> FOLLOWER)
);

counterexample:
-- Under the declared schema, every valid instance of the FOLLOW table makes Q1 and Q2 equivalent. For example, even if you try:
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A','B');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A','C');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('B','A');

-- The results will be:
-- Q1: It considers rows where the FOLLOWEE is in (SELECT FOLLOWER FROM FOLLOW). Here the set of follower values is {A, B, C}. Thus, rows with FOLLOWEE 'A' (from the first two rows) and with FOLLOWEE 'B' (from the third row) qualify, so Q1 returns (A,2) and (B,1).
-- Q2: It uses the join so that F1.FOLLOWER (from the first row: B, from the second: C, from the third: A) groups only those users that themselves appear as FOLLOWEE in some row. The join then finds for user A (from F1 row in third row) the two rows in F2 where FOLLOWEE = 'A', and for user B (from F1 row in first row) the row in F2 where FOLLOWEE = 'B'. Thus, Q2 also returns (A,2) and (B,1).

-- This example shows that under the schema constraints, no counterexample can be produced.

INSERT INTO DELIVERY (DELIVERY_ID, CUSTOMER_ID, ORDER_DATE, CUSTOMER_PREF_DELIVERY_DATE) VALUES (1, 101, '2021-01-01', '2021-01-01');
INSERT INTO DELIVERY (DELIVERY_ID, CUSTOMER_ID, ORDER_DATE, CUSTOMER_PREF_DELIVERY_DATE) VALUES (2, 102, '2021-01-01', '2021-01-01');
INSERT INTO DELIVERY (DELIVERY_ID, CUSTOMER_ID, ORDER_DATE, CUSTOMER_PREF_DELIVERY_DATE) VALUES (3, 103, '2021-01-01', '2021-01-02');

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Test Product', 100);

-- Insert a valid in‐range sale for product 1
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (1, 10, 20, '2019-02-01', 1, 100);

-- Insert an out‐of‐range sale with a NULL PRODUCT_ID (allowed by the schema) to pollute the NOT IN subquery in Q2
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (NULL, 99, 100, '2018-12-30', 1, 100);

