CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

counterexample:
-- No counterexample is possible because the alias in Q2 does not change the computed value. However, here is a sample test data that demonstrates their equivalence:

INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 1);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (200, 1);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (300, 2);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (400, 2);

-- Additionally, if a customer purchased both products, the queries would return that customer:
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (500, 1);
-- Note: Due to the PRIMARY KEY on CUSTOMER, a customer can only appear once. The schema as provided does not allow customers to purchase multiple products because there is a one-to-one correspondence (PRIMARY KEY (CUSTOMER_ID)).

-- Nonetheless, any valid test data in this schema will lead Q1 and Q2 to be equivalent.

