-- Under the current schema and constraints (with (PLAYER_ID, EVENT_DATE) as the primary key), no valid counterexample exists.
-- For illustration, here is some sample data that produces the same result in both queries:

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 10, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-02-01', 11, 3);
