counterexample:
-- NOTE: The following INSERT statements create a counterexample only if the PRODUCT primary key constraint is not enforced.
-- In a proper schema the duplicate insert would be rejected. This example is only valid if duplicates were allowed.

INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);  -- duplicate row to simulate non-distinct count

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 1);

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'S8', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'IPHONE', 1100);

INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 10, 1, '2021-01-01', 1, 100);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 20, NULL, '2021-01-02', 1, 1100);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-12-31', 101, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 101, 3);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-12-30', 102, 4);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-12-31', 102, 2);

-- The following INSERT statements assume that the PK constraint on (PLAYER_ID, EVENT_DATE) is either disabled or not enforced for the sake of the counterexample.

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 100, 1);
-- First activity for player 1 (first login)

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 100, 2);
-- First activity on the day after first login

-- Insert a duplicate row for player 1 on the same day ('2023-01-02')
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 3);

-- For a second player with normal (non-duplicate) data
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-05', 200, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-06', 200, 1);

-- Explanation:
-- For player 1, the TEMP subquery finds MIN_DATE = '2023-01-01'.
-- Q1 joins all activities for player 1 and sums 1 for every activity where EVENT_DATE = '2023-01-02'.
-- Due to the duplicate, Q1's numerator gets 2 counts for player 1. 
-- In Q2, the FIRST_LOGIN CTE returns one row for player 1. When joined to ACTIVITY, each activity (except the first login row) joins against that unique FIRST_LOGIN row. Thus, even though there are duplicate rows on '2023-01-02', the intended logic would be to count only once per player if the implementation were adjusted to de‐duplicate (or if one expected only one eligible row per player). 
-- As a result, Q1 and Q2 yield different FRACTION values for this dataset, highlighting a divergence when duplicate activity rows on the consecutive day occur.

