-- The following INSERT statements create a consistent test database under the given schema.

-- Insert products (each PRODUCT_KEY is unique because of the primary key constraint)
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

-- Insert customers. Each customer is recorded once (PRIMARY KEY on CUSTOMER_ID) and has a single associated PRODUCT_KEY.
-- In this setup every customer’s COUNT(DISTINCT PRODUCT_KEY) = 1 while the total number of products (both COUNT(DISTINCT PRODUCT_KEY) and COUNT(*)) = 2.
-- Thus, neither query returns any rows. Notice that Q1 and Q2 yield the same result.

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 1);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (200, 2);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (300, 1);

-- Explanation:
-- For each customer, COUNT(DISTINCT PRODUCT_KEY) = 1. The subqueries in both Q1 and Q2 return 2, since there are 2 rows in PRODUCT (and the keys are unique).
-- Therefore, the HAVING condition fails for all customers. Under the current schema Q1 and Q2 return exactly the same (empty) set.

-- Note: A counterexample where Q1 and Q2 differ would require that the PRODUCT table contain duplicate PRODUCT_KEY values so that
-- COUNT(DISTINCT PRODUCT_KEY) < COUNT(*). However, this is impossible to achieve without violating the PRIMARY KEY constraint on PRODUCT.

