-- For player 1: one record on 2023-01-01 (first login) and one record on 2023-01-02 (qualifying activity).
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, DATE '2023-01-01', 101, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, DATE '2023-01-02', 101, 3);

-- For player 2: one record on 2023-01-01 (first login) and two records on 2023-01-02 (each a qualifying activity).
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, DATE '2023-01-01', 102, 4);
-- The following two INSERTs intentionally insert duplicate activity records (which would violate the PK constraint if enforced)
