INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, DATE '2023-01-02', 103, 2);

-- Expected outcome if duplicates were allowed:
-- Q1: For player 1, one qualifying row → contributes 1; for player 2, two qualifying rows → contributes 2; numerator = 3. Denom = 2 players → fraction = 1.5 (rounded as 1.50).
-- Q2: It counts distinct players with a qualifying activity. Both players qualify but each counts once → fraction = 2/2 = 1.0 (rounded as 1.00).

-- IMPORTANT: This counterexample uses data that would violate the PRIMARY KEY constraint. Under the given schema (with the PK enforced) a player cannot have two activity rows on the same day and thus no counterexample exists that does not violate the constraints.

schema:
CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
