    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

counterexample:
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 1);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (2, 2);

-- Assume that due to an ETL issue the ACTIVITY table can contain duplicate activity records for a given player and day
-- (i.e. the PK constraint is not enforced in the load stage even though it is declared in the schema).

-- Player 1’s first login is 2021-01-01. That same player has two activity records on 2021-01-02 (the day after install).

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 100, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 101, 3);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 102, 2);

-- Also insert another player (Player 2) who installs on 2021-01-01 and has a single activity on 2021-01-02
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-01', 200, 8);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-02', 201, 4);

-- Results:
-- In Q1, the join for 2021-01-01 will produce for Player 1 two rows (both from 2021-01-02 match) and one row for Player 2.
-- The SUM(CASE...) in Q1 will sum to 2 (Player 1 contributes 2 and Player 2 contributes 1) and the distinct count of players is 2, giving a calculated retention of 2/2 = 1.00.
-- In Q2, the left join is defined so that a player’s retention is counted at most once. Thus Player 1 counts as 1 and Player 2 as 1, with retention = 2/2 = 1.00.

-- Now, if the intent had been to count each player only once in the numerator, Q1 would be overcounting retention if the duplicates are not de‐duplicated. (In many reporting scenarios such duplicates are unexpected but not unheard of in raw log data before cleaning.)

-- Hence, the counterexample shows that when duplicate day–1 activities occur for a player, Q1 and Q2 can return different day1 retention values.

