-- The following INSERT statements create test data for two players installed on 2023-01-01.
-- PLAYER 1 has duplicate ACTIVITY records on 2023-01-02 (simulating duplicate day1 events even though the PK would normally prevent it).
-- PLAYER 2 has a single ACTIVITY record on 2023-01-02 (normal behavior).

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 100, 1);
-- For PLAYER 1, we simulate duplicate records on day1. In a real system these duplicates may occur despite the logical PK constraint.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 100, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 3);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-01', 102, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-02', 102, 6);

-- When running Q1 and Q2:
-- For installation date '2023-01-01', Q1 will compute INSTALLS = 2 (players 1 and 2), but its numerator will sum to 3 (2 from PLAYER 1 and 1 from PLAYER 2),
-- yielding DAY1_RETENTION = 3/2 = 1.50 (which rounds to 1.50), while Q2 will count distinct players in the numerator (1 for PLAYER 1 and 1 for PLAYER 2),
-- yielding DAY1_RETENTION = 2/2 = 1.00.

-- This difference in handling duplicates in the retention day is the intended divergence.

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Product A', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'Product B', 200);

