-- This sales record, with a NULL PRODUCT_ID and a sale date outside the period, causes the subquery in Q2 to return a NULL value
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (NULL, 12, 22, '2018-12-31', 1, 50);

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Product A', 10);

-- Valid sale for product 1 inside the quarter
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 100, 200, '2019-02-15', 1, 10);

-- A sale record with PRODUCT_ID as NULL, outside the quarter, which will appear in the NOT IN subquery
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (NULL, 101, 201, '2019-12-01', 1, 10);

