-- The following INSERTs assume that the ACTIVITY table did not enforce a unique constraint on (PLAYER_ID, EVENT_DATE) so that duplicate records for a player on the same day are allowed. (Note that this counterexample violates the declared PRIMARY KEY constraint, but it nevertheless illustrates the semantic difference in how the two queries aggregate data.)

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 100, 3);
-- Player 1: first activity date is 2023-01-01
-- Two activities on the next day (2023-01-02) that would qualify
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 4);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 102, 5);

-- Player 2: only one activity, on 2023-01-10 (so does not qualify because there is no event on 2023-01-11, and the first day is 2023-01-10)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-10', 200, 2);

-- Under this data:
-- Q1 will compute the numerator as (2 from player 1 + 0 from player 2) = 2 and the denominator as 2 (two players), yielding a fraction of 1.00 when rounded (if no fractional arithmetic is forced).
-- Q2 will count player 1 only once in its numerator and player 2 in its denominator, yielding a fraction of 0.50.

-- IMPORTANT: Under the declared schema (with PRIMARY KEY (PLAYER_ID, EVENT_DATE)) this counterexample cannot occur. It only illustrates that if duplicate events per day were allowed, the two queries would produce different results.

INSERT INTO DELIVERY (DELIVERY_ID, CUSTOMER_ID, ORDER_DATE, CUSTOMER_PREF_DELIVERY_DATE) VALUES (1, 101, '2023-01-01', '2023-01-01');

-- Even though DELIVERY_ID is declared as PRIMARY KEY, assume for the sake of the counterexample that a row with a NULL DELIVERY_ID can be inserted
INSERT INTO DELIVERY (DELIVERY_ID, CUSTOMER_ID, ORDER_DATE, CUSTOMER_PREF_DELIVERY_DATE) VALUES (NULL, 102, '2023-01-01', '2023-01-02');

