-- Note: Alice has no bonus record, so the LEFT JOIN produces a NULL bonus value. 
-- In Q2 the WHERE clause “BONUS.BONUS IS NULL” will include Alice, whereas in Q1 an unqualified BONUS in some systems might be misresolved and discard Alice.

schema:
CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

