-- Insert one valid product (product 1 exists in PRODUCT)
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'ValidProduct', 100);

-- Insert a sale for product 1 (this product qualifies if its sale date is in Q1)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE)
VALUES (1, 10, 20, '2019-02-15', 1, 100);

-- Insert a sale for product 2 (which is within Q1) but do not insert product 2 into PRODUCT
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE)
VALUES (2, 11, 21, '2019-02-20', 1, 200);

/*
   With these data:
   • Q1 will do an inner join on PRODUCT. For product_id = 2 there is no PRODUCT row, so Q1 will return only product 1.
   • Q2, however, starts from SALES. The sale for product 2 is present and, after the LEFT JOIN, PRODUCT fields will be NULL. The GROUP BY will yield a row for product_id = 2 (with PRODUCT_NAME NULL) because the HAVING condition on SALE_DATE is met.
   Thus the two queries output different results.
*/

