INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES (1, '2023-01-01', 'MOBILE', 20);

-- These two rows cause user 1 to have spending on both platforms on 2023-01-01, so the computed aggregated platform is 'BOTH'.

-- In addition, insert multiple rows for another date so that the sub–query producing the (SPEND_DATE, PLATFORM) buckets might (in some systems) return duplicates when using UNION ALL:

INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES (2, '2023-01-02', 'DESKTOP', 15);
INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES (3, '2023-01-02', 'MOBILE', 25);
INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES (4, '2023-01-02', 'DESKTOP', 20);
INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES (5, '2023-01-02', 'MOBILE', 30);

-- In some SQL engines the ORG CTE in Q2 might produce duplicate (SPEND_DATE, PLATFORM) rows for 2023-01-02 because of the UNION ALL, causing the same aggregated row(s) from B to join more than once. Then Q1 (using COUNT(USER_ID)) would add up such duplicates while Q2’s COUNT(DISTINCT USER_ID) would not. This data setup is a small test database where running Q1 and Q2 can produce different TOTAL_USERS counts for the affected (SPEND_DATE, PLATFORM) groups.

