counterexample:
/*
Note: The following INSERT statements intentionally create a situation (duplicate rows in PRODUCT) that violates the declared PRIMARY KEY constraint on PRODUCT. This counterexample is only valid if the constraint is relaxed or not enforced. */

BEGIN;

-- In a system where the primary key constraint on PRODUCT is not enforced,
-- insert duplicate rows into PRODUCT to simulate duplicate products.
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);  -- duplicate row, causing COUNT(PRODUCT_KEY) to be 2 but COUNT(DISTINCT PRODUCT_KEY) remains 1

-- Insert a customer who purchased product 1 (and thus the only distinct product).
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 1);

COMMIT;

/*
Running Q1:
  SELECT CUSTOMER_ID FROM CUSTOMER GROUP BY 1 
    HAVING COUNT(DISTINCT PRODUCT_KEY) = (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT);

  The subquery returns 1 (since only product 1 is distinct) so customer 100 qualifies.

Running Q2:
  SELECT CUSTOMER_ID FROM CUSTOMER GROUP BY CUSTOMER_ID 
    HAVING COUNT(DISTINCT PRODUCT_KEY) = (SELECT COUNT(PRODUCT_KEY) AS CNT FROM PRODUCT);

  The subquery returns 2 (because the duplicate is counted) so customer 100 does not qualify.
*/

