CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

counterexample:
-- No counterexample can be generated because, under the provided schema constraints, the two queries are equivalent.
-- For illustration, here is some sample data that, when inserted, will yield the same result for Q1 and Q2:

INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (10, 1);
-- This customer has purchased one product, so will not appear unless all products are purchased.

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (20, 1);
-- Again, this customer purchased one product.

-- In order for a customer to meet the condition (purchased both products), we need a customer with PRODUCT_KEY = 1 and PRODUCT_KEY = 2.
-- However, given that CUSTOMER.CUSTOMER_ID is the primary key, each customer can appear only once. Therefore, under the given schema it is not possible to model a customer who purchased two different products in separate rows.

-- As a consequence, since the only allowed grouping is on unique CUSTOMER_ID values, both queries will always have the same result no matter the data inserted.

