INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 1, 10);
-- The following two inserts simulate duplicate records for player 1 on the day after his first activity
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 1, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 2, 8);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-01', 1, 12);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-03', 1, 7);

-- When run on this data:
-- Q1 will compute SUM(case...) = 2 (two matching rows for player 1) and COUNT(DISTINCT PLAYER_ID) = 2, yielding 2/2 = 1.00
-- Q2 will compute COUNT(DISTINCT A.PLAYER_ID) = 1 (player 1 is counted only once) and COUNT(DISTINCT B.PLAYER_ID) = 2, yielding 1/2 = 0.50
-- Thus the results differ.

