SET FOREIGN_KEY_CHECKS = 0;

-- Insert a project that references a non-existent employee (employee 2)
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (200, 2);

SET FOREIGN_KEY_CHECKS = 1;

/*
When running Q1 and Q2 on this data:
  • Q1 (inner join) will only see the project with PROJECT_ID 100 (from employee 1) and return an average of 5.
  • Q2 (left join subquery) will return both projects. For PROJECT_ID 200, EXPERIENCE_YEARS is NULL so AVG is NULL.
Thus, the two queries produce different results.
*/

