INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-02-05', 201, 4);

-- For PLAYER_ID 1, both queries return the row with EVENT_DATE '2023-01-01';
-- For PLAYER_ID 2, both queries return the row with EVENT_DATE '2023-02-01'.

-- Thus, within the allowed constraints, Q1 and Q2 are equivalent.

