INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (1, 1);

-- Expected Results:
-- Q1: For project 1, the joined rows are two rows with experience 4, so AVG = (4+4)/2 = 4.00
-- Q2: The CTE groups the rows by (PROJECT_ID, EMPLOYEE_ID) so it produces one row with SUM = 4+4 = 8, and then AVG = 8.00

