counterexample:
-- No counterexample is possible because the schema's PRIMARY KEY (FOLLOWEE, FOLLOWER) ensures that COUNT(FOLLOWEE) and COUNT(DISTINCT FOLLOWER) yield the same value for each followee.
-- However, to illustrate the typical data, here are some INSERT statements that produce equal outputs for Q1 and Q2:
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Alice', 'Bob');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Alice', 'Charlie');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Bob', 'Alice');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Bob', 'Charlie');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Charlie', 'Alice');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Charlie', 'Bob');

-- The following INSERT statements assume that the PRIMARY KEY constraint is either dropped or bypassed so that a player can have duplicate events for a given day.

-- Player 1 installs on 2023-01-01 and then has two events on 2023-01-02 (day1), which will make Q1 count two retention events for this player while Q2 effectively counts it once.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 101, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 102, 1);

-- Player 2 installs on 2023-01-01 and has a single event on 2023-01-02.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-01', 201, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-02', 201, 1);

-- In Q1 for install date 2023-01-01:
--   Denom = COUNT(DISTINCT PLAYER_ID) = 2
--   Numerator = for player 1: 2 (because there are two rows on 2023-01-02) and for player 2: 1, so total = 3
--   DAY1_RETENTION = ROUND(3/2,2) = 1.50

-- In Q2 for install date 2023-01-01:
--   The WITH clause produces one row per player.
--   The LEFT JOIN on ACTIVITY (with date filter) will join player 1 to two rows and player 2 to one row, making the aggregate row count 3; however, both numerator and denominator are inflated by the same factor for player 1, so the overall retention becomes COUNT(A.PLAYER_ID)/COUNT(I.PLAYER_ID) = 3/3 = 1.00

-- Thus, Q1 returns a DAY1_RETENTION of 1.50 while Q2 returns 1.00 for the same install date, showing that the two queries are not equivalent when duplicate day‑1 events occur.

