-- A valid sale for product 1, within the date range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (1, 101, 201, '2019-02-15', 1, 100);

-- A rogue sale record with PRODUCT_ID = NULL and SALE_DATE outside the range
-- This row does not affect Q1 because it groups by PRODUCT_ID (grouping NULL separately) 
-- but it makes the NOT IN subquery in Q2 return NULL, so that for any product X, 'X NOT IN (NULL, ...)' yields false.
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (NULL, 102, 202, '2018-12-31', 1, 50);

