-- | CUSTOMERS |
-- | Bob       |

-- Hence, no counterexample exists.

schema:
CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR(255),
    FOLLOWER VARCHAR(255),
    PRIMARY KEY (FOLLOWEE, FOLLOWER),
    CHECK (FOLLOWEE <> FOLLOWER)
);

counterexample:
-- The following INSERTs provide an example data set, but note that Q1 and Q2 will return the same results for this data:

INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A', 'B');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('B', 'A');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('B', 'C');

-- Explanation:
-- The subquery in Q1 (SELECT FOLLOWER FROM FOLLOW) returns { 'B', 'A', 'C' }.
-- Thus the outer query of Q1 selects only those rows whose FOLLOWEE is in that set. In this data, that means the row for 'A' (because 'A' appears as a follower in ('B','A')) and the rows for 'B' (because 'B' appears as a follower in ('A','B')).
-- Similarly, the subquery in Q2 (which is based on a join yielding users who appear both as followee and as follower) returns { 'A', 'B' } and the outer query then groups by FOLLOWEE. In both cases the computed counts match (each group has one or more rows, and duplicates cannot occur because of the primary key).

-- Therefore, under the given schema there is no counterexample where Q1 and Q2 produce different results.

